cat > src/color.js <<'EOF'
/**
 * Terminal color support detection, using Node's built-in tty APIs plus the
 * common conventions:
 *   - `--no-color` / `--color` CLI flags (highest priority)
 *   - NO_COLOR (https://no-color.org) disables color
 *   - FORCE_COLOR enables color, even when output is piped (`0`/`false` disables)
 *   - TERM=dumb disables color
 *   - Output that is not a TTY (piped/redirected) gets no color by default
 */

const ANSI = {
  reset: 0,
  bold: 1,
  dim: 2,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  gray: 90,
};

/**
 * @param {NodeJS.WriteStream} [stream]
 * @param {{ argv?: string[], env?: NodeJS.ProcessEnv }} [options]
 * @returns {boolean}
 */
export function supportsColor(
  stream = process.stdout,
  { argv = process.argv, env = process.env } = {},
) {
  if (argv.includes('--no-color')) return false;
  if (argv.includes('--color')) return true;

  if ('FORCE_COLOR' in env) {
    return !['0', 'false'].includes(env.FORCE_COLOR);
  }
  if ('NO_COLOR' in env && env.NO_COLOR !== '') return false;
  if (env.TERM === 'dumb') return false;

  if (!stream?.isTTY) return false;

  // tty.WriteStream#hasColors() inspects TERM, COLORTERM, CI vars, Windows
  // version, etc. Pass env explicitly so the injected env is honored.
  if (typeof stream.hasColors === 'function') {
    return stream.hasColors(env);
  }
  return true;
}

/**
 * Build a set of color functions bound to a stream. When the stream doesn't
 * support color, every function returns its input unchanged.
 *
 * @param {NodeJS.WriteStream} [stream]
 * @param {{ argv?: string[], env?: NodeJS.ProcessEnv, enabled?: boolean }} [options]
 */
export function createColors(stream = process.stdout, options = {}) {
  const enabled = options.enabled ?? supportsColor(stream, options);
  const colors = { enabled };
  for (const [name, code] of Object.entries(ANSI)) {
    if (name === 'reset') continue;
    const close = name === 'bold' || name === 'dim' ? 22 : 39;
    colors[name] = enabled
      ? (text) => `\x1b[${code}m${text}\x1b[${close}m`
      : (text) => String(text);
  }
  return colors;
}
EOF
cat > bin/cli.js <<'EOF'
#!/usr/bin/env node
import { createColors } from '../src/color.js';

const out = createColors(process.stdout);
const err = createColors(process.stderr);

const args = process.argv.slice(2).filter((a) => a !== '--color' && a !== '--no-color');

if (args.includes('--help') || args.includes('-h')) {
  console.log(`Usage: color-cli [--color | --no-color] [name]

Options:
  --color      Force colored output
  --no-color   Disable colored output
  -h, --help   Show this help

Environment:
  NO_COLOR     Disable colored output
  FORCE_COLOR  Force colored output (0 or false to disable)`);
  process.exit(0);
}

const name = args[0] ?? 'world';

console.log(`${out.bold('Hello,')} ${out.green(name)}!`);
console.log(out.gray(`stdout colors: ${out.enabled ? 'on' : 'off'}`));

if (name === 'error') {
  console.error(err.red('Example error message on stderr'));
  process.exitCode = 1;
}
EOF
chmod +x bin/cli.js
cat > test/color.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { supportsColor, createColors } from '../src/color.js';

const tty = { isTTY: true, hasColors: () => true };
const pipe = { isTTY: false };

test('piped output has no color by default', () => {
  assert.equal(supportsColor(pipe, { argv: [], env: {} }), false);
});

test('TTY with color support enables color', () => {
  assert.equal(supportsColor(tty, { argv: [], env: {} }), true);
});

test('TTY without color support (hasColors false) disables color', () => {
  const mono = { isTTY: true, hasColors: () => false };
  assert.equal(supportsColor(mono, { argv: [], env: {} }), false);
});

test('NO_COLOR disables color on a TTY', () => {
  assert.equal(supportsColor(tty, { argv: [], env: { NO_COLOR: '1' } }), false);
});

test('empty NO_COLOR is ignored', () => {
  assert.equal(supportsColor(tty, { argv: [], env: { NO_COLOR: '' } }), true);
});

test('TERM=dumb disables color', () => {
  assert.equal(supportsColor(tty, { argv: [], env: { TERM: 'dumb' } }), false);
});

test('FORCE_COLOR enables color when piped', () => {
  assert.equal(supportsColor(pipe, { argv: [], env: { FORCE_COLOR: '1' } }), true);
  assert.equal(supportsColor(pipe, { argv: [], env: { FORCE_COLOR: '' } }), true);
});

test('FORCE_COLOR=0 disables color', () => {
  assert.equal(supportsColor(tty, { argv: [], env: { FORCE_COLOR: '0' } }), false);
});

test('CLI flags override environment', () => {
  assert.equal(supportsColor(pipe, { argv: ['--color'], env: { NO_COLOR: '1' } }), true);
  assert.equal(supportsColor(tty, { argv: ['--no-color'], env: { FORCE_COLOR: '1' } }), false);
});

test('createColors returns plain text when disabled', () => {
  const c = createColors(pipe, { argv: [], env: {} });
  assert.equal(c.enabled, false);
  assert.equal(c.red('hi'), 'hi');
});

test('createColors wraps text in ANSI codes when enabled', () => {
  const c = createColors(tty, { argv: [], env: {} });
  assert.equal(c.red('hi'), '\x1b[31mhi\x1b[39m');
  assert.equal(c.bold('hi'), '\x1b[1mhi\x1b[22m');
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
EOF
cat > README.md <<'EOF'
# color-cli

A dependency-free Node.js CLI that checks whether the terminal supports color before printing colored text.

## Usage

```sh
npm start -- Alice          # colored if stdout is a color-capable TTY
node bin/cli.js | cat       # piped: plain text
NO_COLOR=1 node bin/cli.js  # plain text
FORCE_COLOR=1 node bin/cli.js | cat   # colored even when piped
node bin/cli.js --no-color  # plain text
```

## How detection works (`src/color.js`)

Checks run in this order, and the first match wins:

1. `--no-color` / `--color` flags
2. `FORCE_COLOR` (enables color; `0` or `false` disables it)
3. `NO_COLOR` set to a non-empty value disables color ([no-color.org](https://no-color.org))
4. `TERM=dumb` disables color
5. Output that isn't a TTY (piped or redirected) gets no color
6. Otherwise, Node's `tty.WriteStream#hasColors()` decides, based on TERM, COLORTERM, CI, and Windows version

stdout and stderr are checked separately, so `cli 2>err.log` still colors stdout.

## Tests

```sh
npm test
```
EOF
npm test 2>&1 | tail -12
echo ---; node bin/cli.js Alice | od -c | head -3
echo ---; FORCE_COLOR=1 node bin/cli.js Alice | od -c | head -3
echo ---; node bin/cli.js --color | cat -v

